    const total = lineTotal(line);
    const qty = line.qty;
    const name = line.name;
    const unitPrice = formatEuros(line.unitPrice);
    const lineTotal_formatted = formatEuros(total);

    if (line.discountPercent) {
      const discount = lineDiscount(line);
      const discountFormatted = formatEuros(discount);
      const netTotal = total - discount;
      const netFormatted = formatEuros(netTotal);
      lines.push(`${qty} ${name} ${unitPrice} ${lineTotal_formatted} -${line.discountPercent}% ${discountFormatted} ${netFormatted}`);
    } else {
      lines.push(`${qty} ${name} ${unitPrice} ${lineTotal_formatted}`);
    }
  }

  // Totals
  const totals = invoiceTotals(invoice);
  const subtotalFormatted = formatEuros(totals.subtotal);
  const discountFormatted = formatEuros(totals.discount);
  const vatFormatted = formatEuros(totals.vat);
  const totalFormatted = formatEuros(totals.total);

