import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';
import { createInvoice, issueInvoice, applyVoucher } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('renderInvoiceText shows DRAFT for unsent invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const text = renderInvoiceText(invoice);
  assert.match(text, /^DRAFT\n/);
});

test('renderInvoiceText shows invoice number for issued invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const text = renderInvoiceText(issued);
  assert.match(text, /^INV-2025-0001\n/);
});

test('renderInvoiceText includes customer name', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const text = renderInvoiceText(invoice);
  assert.match(text, /Northwind Studio/);
});

test('renderInvoiceText formats single line correctly', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const text = renderInvoiceText(invoice);
  assert.match(text, /5 Design work \(hour\) €85\.00 €425\.00/);
});

test('renderInvoiceText shows all lines', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'ICON-SET', qty: 2 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  assert.match(text, /5 Design work/);
  assert.match(text, /10 Development/);
  assert.match(text, /2 Icon set/);
});

test('renderInvoiceText calculates correct line totals', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 2 }, // 2 * €85.00 = €170.00
      { sku: 'DEV-HOUR', qty: 3 }, // 3 * €95.00 = €285.00
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  assert.match(text, /2 Design work \(hour\) €85\.00 €170\.00/);
  assert.match(text, /3 Development \(hour\) €95\.00 €285\.00/);
});

test('renderInvoiceText shows correct invoice total', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // standard tier, no discount
    issueDate: '2025-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 2 }, // €170.00
      { sku: 'DEV-HOUR', qty: 3 }, // €285.00
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  // Subtotal: €455.00, VAT 21%: €95.55, Total: €550.55
  assert.match(text, /Total: €550\.55/);
});

test('renderInvoiceText formats multi-line output correctly', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // standard tier, no discount
    issueDate: '2025-10-15',
    lines: [
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'ICON-SET', qty: 5 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Blue Fern Bakery');
  assert.ok(lines[2].includes('Logo package'));
  assert.ok(lines[3].includes('Icon set'));
  // Should have subtotal, VAT, and total lines
  const textStr = text;
  assert.match(textStr, /Subtotal:/);
  assert.match(textStr, /VAT:/);
  assert.match(textStr, /Total:/);
});

test('renderInvoiceText handles different quantities and prices', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // standard tier, no discount
    issueDate: '2025-10-15',
    lines: [
      { sku: 'PRINT-A4', qty: 100 }, // 100 * €0.37 = €37.00 - bulk 2.5% €0.92 = €36.08, VAT 9% = €3.25
      { sku: 'STICKER', qty: 1000 }, // 1000 * €0.50 = €500.00 - bulk 2.5% €12.50 = €487.50, VAT 21% = €102.38
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  assert.match(text, /100 Printed flyer/);
  assert.match(text, /1000 Sticker/);
  // Subtotal: €537.00, Discount: €13.42, VAT: €105.63, Total: €629.21
  assert.match(text, /Total: €629\.21/);
});

test('renderInvoiceText uses formatEuros for all amounts', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'PHOTO-LIC', qty: 1 }], // €9.96
  }).value;

  const text = renderInvoiceText(invoice);
  // All amounts should have two decimal places and euro sign
  assert.match(text, /€\d+\.\d{2}/);
  const matches = text.match(/€\d+\.\d{2}/g);
  assert.ok(matches.length >= 2); // At least unitPrice and line total
});

test('renderInvoiceText handles issued invoice with previous numbers', () => {
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const invoice2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-20',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  }).value;

  const existing = ['INV-2025-0001', 'INV-2025-0002'];
  const issued = issueInvoice(invoice2, existing).value;

  const text = renderInvoiceText(issued);
  assert.match(text, /^INV-2025-0003\n/);
});

test('renderInvoiceText shows different customer names', () => {
  const c1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const c2 = createInvoice({
    customerId: 'C-008',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const text1 = renderInvoiceText(c1);
  const text2 = renderInvoiceText(c2);

  assert.match(text1, /Northwind Studio/);
  assert.match(text2, /Lumen Records/);
});

test('renderInvoiceText shows discount on line with discountPercent', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 10 }], // €850 - €85 - bulk 2.5% €19.12 = €745.88
  }).value;

  const text = renderInvoiceText(invoice);
  assert.match(text, /-10%/);
  assert.match(text, /Total: €902\.51/); // with bulk discount and VAT
});

test('renderInvoiceText shows subtotal and discount when there are discounts', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 20 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  assert.match(text, /Subtotal: €1,325\.00/);
  assert.match(text, /Discount: -€199\.12/);
  assert.match(text, /VAT: €236\.43/);
  assert.match(text, /Total: €1,362\.31/);
});

test('renderInvoiceText shows only Subtotal and Total when no discounts or VAT', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // standard tier, no discount
    issueDate: '2025-10-15',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }], // VAT-exempt (0%)
  }).value;

  const text = renderInvoiceText(invoice);
  assert.match(text, /Subtotal:/);
  assert.ok(!text.match(/Discount:/));
  assert.ok(!text.match(/VAT:/));
  assert.match(text, /Total:/);
});

test('renderInvoiceText shows line without discount normally', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }], // €425 with no discount
  }).value;

  const text = renderInvoiceText(invoice);
  assert.match(text, /5 Design work \(hour\) €85\.00 €425\.00/);
  assert.ok(!text.match(/-%/));
});

test('renderInvoiceText displays decimal discount percentages', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 4, discountPercent: 12.5 }], // €340 - €42.50 = €297.50
  }).value;

  const text = renderInvoiceText(invoice);
  assert.match(text, /-12\.5%/);
  assert.match(text, /€297\.50/); // net after discount
});

test('renderInvoiceText calculates correct discount amounts', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 10 }, // €1200 - €120 = €1080
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  assert.match(text, /€120\.00/); // discount amount
  assert.match(text, /€1,080\.00/); // net total
  assert.match(text, /Subtotal: €1,200\.00/);
  assert.match(text, /Discount: -€120\.00/);
});

test('renderInvoiceText shows VAT when present', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // standard tier
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }], // €850 * 21% VAT
  }).value;

  const text = renderInvoiceText(invoice);
  assert.match(text, /VAT:/);
  assert.match(text, /Subtotal:/);
  assert.match(text, /Total:/);
});

test('renderInvoiceText does not show VAT line when VAT is 0', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }], // 0% VAT
  }).value;

  const text = renderInvoiceText(invoice);
  assert.ok(!text.match(/VAT:/));
  assert.match(text, /Subtotal:/);
  assert.match(text, /Total:/);
});

test('renderInvoiceText VAT is calculated on net amount after discount', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 10 }], // €850 - €85 - bulk 2.5% €19.12 = €745.88, VAT €156.63
  }).value;

  const text = renderInvoiceText(invoice);
  assert.match(text, /Subtotal: €850\.00/);
  assert.match(text, /Discount: -€104\.12/);
  assert.match(text, /VAT: €156\.63/);
  assert.match(text, /Total: €902\.51/);
});

test('renderInvoiceText shows all VAT-related lines in correct order', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  // Find the positions of subtotal, discount, VAT, and total
  const lastLineIdx = lines.length - 1;
  const totalIdx = lines.findIndex(l => l.startsWith('Total:'));
  const vatIdx = lines.findIndex(l => l.startsWith('VAT:'));
  const discountIdx = lines.findIndex(l => l.startsWith('Discount:'));
  const subtotalIdx = lines.findIndex(l => l.startsWith('Subtotal:'));

  // Verify order: Subtotal -> Discount -> VAT -> Total
  assert.ok(subtotalIdx < discountIdx);
  assert.ok(discountIdx < vatIdx);
  assert.ok(vatIdx < totalIdx);
});

test('renderInvoiceText with multiple lines and mixed VAT rates', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 }, // €425, VAT 21% = €89.25
      { sku: 'PRINT-A4', qty: 100 }, // €37 - bulk 2.5% €0.92 = €36.08, VAT 9% = €3.25
      { sku: 'WORKSHOP-DAY', qty: 1 }, // €600, VAT 0% = €0
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  assert.match(text, /Subtotal: €1,062\.00/);
  assert.match(text, /VAT: €92\.50/); // €89.25 + €3.25 + €0
  assert.match(text, /Total: €1,153\.58/);
});

test('renderInvoiceText shows correct formatting with discount and VAT', () => {
  const invoice = createInvoice({
    customerId: 'C-001', // gold tier (5% discount)
    issueDate: '2025-10-15',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }], // €1200, discount 5% = €60, net €1140, VAT 21% = €239.40
  }).value;

  const text = renderInvoiceText(invoice);
  assert.match(text, /Subtotal: €1,200\.00/);
  assert.match(text, /Discount: -€60\.00/);
  assert.match(text, /VAT: €239\.40/);
  assert.match(text, /Total: €1,379\.40/);
});

test('renderInvoiceText shows voucher before total', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }], // 20570 cents
  }).value;
  const withVoucher = applyVoucher(invoice, { code: 'WELCOME10', amount: 5000 }).value;

  const text = renderInvoiceText(withVoucher);
  const lines = text.split('\n');

  // Find voucher and total lines
  const voucherIdx = lines.findIndex(l => l.includes('WELCOME10'));
  const totalIdx = lines.findIndex(l => l.startsWith('Total:'));

  // Voucher should appear before Total
  assert.ok(voucherIdx >= 0, 'voucher line exists');
  assert.ok(voucherIdx < totalIdx, 'voucher appears before total');
  assert.match(text, /Voucher \(WELCOME10\): -€50\.00/);
