test('renderInvoiceText does not show due date for draft invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const text = renderInvoiceText(invoice);
