import { formatEuros } from './money.js';
import { getCustomer } from './customers.js';
import { invoiceTotals, lineTotal, lineDiscount, lineVAT } from './invoices.js';
import { balanceDue } from './payments.js';

/**
 * Render an invoice as plain text for display to a customer.
 * @param {{ customerId: string, number?: string, lines: Array<{ qty: number, name: string, unitPrice: number, discountPercent?: number }> }}
 * @returns {string} plain-text invoice
 */
export function renderInvoiceText(invoice) {
  // Get customer name
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : 'Unknown Customer';

  // Build lines
  const lines = [];

  // Invoice number or DRAFT
  const invoiceNumber = invoice.number ?? 'DRAFT';
  lines.push(invoiceNumber);

  // Customer name
  lines.push(customerName);

  // Invoice lines
  for (const line of invoice.lines) {
    const total = lineTotal(line);
    const qty = line.qty;
    const name = line.name;
    const unitPrice = formatEuros(line.unitPrice);
    const lineTotal_formatted = formatEuros(total);

    if (line.discountPercent) {
      const discount = lineDiscount(line);
      const discountFormatted = formatEuros(discount);
      const netTotal = total - discount;
      const netFormatted = formatEuros(netTotal);
      lines.push(`${qty} ${name} ${unitPrice} ${lineTotal_formatted} -${line.discountPercent}% ${discountFormatted} ${netFormatted}`);
    } else {
      lines.push(`${qty} ${name} ${unitPrice} ${lineTotal_formatted}`);
    }
  }

  // Totals
  const totals = invoiceTotals(invoice);
  const subtotalFormatted = formatEuros(totals.subtotal);
  const discountFormatted = formatEuros(totals.discount);
  const vatFormatted = formatEuros(totals.vat);
  const totalFormatted = formatEuros(totals.total);

  lines.push(`Subtotal: ${subtotalFormatted}`);
  if (totals.discount > 0) {
    lines.push(`Discount: -${discountFormatted}`);
  }
  if (totals.vat > 0) {
    lines.push(`VAT: ${vatFormatted}`);
  }

  // Voucher
  if (invoice.voucher) {
    const voucherFormatted = formatEuros(invoice.voucher.amount);
    lines.push(`Voucher (${invoice.voucher.code}): -${voucherFormatted}`);
  }

  lines.push(`Total: ${totalFormatted}`);

  // Due date
  if (invoice.dueDate) {
    lines.push(`Due: ${invoice.dueDate}`);
  }

  // Payments
  if (invoice.payments && invoice.payments.length > 0) {
    const amountPaid = invoice.payments.reduce((sum, p) => sum + p.amount, 0);
    const amountPaidFormatted = formatEuros(amountPaid);
    lines.push(`Paid: ${amountPaidFormatted}`);
  }

  return lines.join('\n');
}

