test('renderInvoiceText shows all details: voucher, due, and partial payment', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2025-10-15',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }], // 120000 cents, silver 2.5%, net 117000, VAT 24570
    terms: 'EOM',
  }).value;
  let withVoucher = applyVoucher(invoice, { code: 'NEW2025', amount: 10000 }).value;
  let issued = issueInvoice(withVoucher, []).value;
  issued = recordPayment(issued, { amount: 50000, date: '2025-10-20' }).value;

  const text = renderInvoiceText(issued);
  const lines = text.split('\n');

  // Check order: Total -> Voucher -> Due -> Paid
  const totalIdx = lines.findIndex(l => l.startsWith('Total:'));
  const voucherIdx = lines.findIndex(l => l.includes('NEW2025'));
  const dueIdx = lines.findIndex(l => l.startsWith('Due:'));
  const paidIdx = lines.findIndex(l => l.startsWith('Paid:'));

  assert.ok(totalIdx < voucherIdx, 'total before voucher');
  assert.ok(voucherIdx < dueIdx, 'voucher before due');
  assert.ok(dueIdx < paidIdx, 'due before paid');
});
